Veo3VideoGenerationNode.schema:
IO.Schema(node_id='Veo3VideoGenerationNode', display_name='Google Veo 3 Video Generation', category='partner/video/Veo', description="Generates videos from text prompts using Google's Veo 3 API", inputs=[IO.String.Input('prompt', multiline=True, default='', tooltip='Text description of the video'), IO.Combo.Input('aspect_ratio', options=['16:9', '9:16'], default='16:9', tooltip='Aspect ratio of the output video'), IO.Combo.Input('resolution', options=['720p', '1080p', '4k'], default='720p', tooltip='Output video resolution. 4K is not available for veo-3.1-lite and veo-3.0 models.', optional=True), IO.String.Input('negative_prompt', multiline=True, default='', tooltip='Negative text prompt to guide what to avoid in the video', optional=True), IO.Int.Input('duration_seconds', default=8, min=4, max=8, step=2, display_mode=IO.NumberDisplay.number, tooltip='Duration of the output video in seconds', optional=True), IO.Boolean.Input('enhance_prompt', default=True, tooltip='This parameter is deprecated and ignored.', optional=True, advanced=True), IO.Combo.Input('person_generation', options=['ALLOW', 'BLOCK'], default='ALLOW', tooltip='Whether to allow generating people in the video', optional=True, advanced=True), IO.Int.Input('seed', default=0, min=0, max=4294967295, step=1, display_mode=IO.NumberDisplay.number, control_after_generate=True, tooltip='Seed for video generation (0 for random)', optional=True), IO.Image.Input('image', tooltip='Optional reference image to guide video generation', optional=True), IO.Combo.Input('model', options=['veo-3.1-generate', 'veo-3.1-fast-generate', 'veo-3.1-lite', 'veo-3.0-generate-001', 'veo-3.0-fast-generate-001'], tooltip='Veo 3 model to use for video generation', optional=True), IO.Boolean.Input('generate_audio', default=False, tooltip='Generate audio for the video. Supported by all Veo 3 models.', optional=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_sim_org, IO.Hidden.api_key_sim_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['model', 'generate_audio', 'resolution', 'duration_seconds']), expr='
                (
                  $m := widgets.model;
                  $r := widgets.resolution;
                  $a := widgets.generate_audio;
                  $seconds := widgets.duration_seconds;
                  $pps :=
                    $contains($m, "lite")
                      ? ($r = "1080p" ? ($a ? 0.08 : 0.05) : ($a ? 0.05 : 0.03))
                    : $contains($m, "3.1-fast")
                      ? ($r = "4k" ? ($a ? 0.30 : 0.25) : $r = "1080p" ? ($a ? 0.12 : 0.10) : ($a ? 0.10 : 0.08))
                    : $contains($m, "3.1-generate")
                      ? ($r = "4k" ? ($a ? 0.60 : 0.40) : ($a ? 0.40 : 0.20))
                    : $contains($m, "3.0-fast")
                      ? ($a ? 0.15 : 0.10)
                    : ($a ? 0.40 : 0.20);
                  {"type":"usd","usd": $pps * $seconds}
                )
                '))

